// A stand-in for the datamine, served locally so the scenarios can run the real generator and the
// real build against data they control. Every row is invented and every "image" is generated bytes:
// not even a test fixture may be a game image (docs/RULES.md).
import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';

type Version = { kits: string[]; gear: string[] };

const weapon = (id: string) => ({
  __RowId: id,
  Type: 'Versus',
  SubWeapon: `Work/Gyml/Sub_${id}.spl__WeaponInfoSub.gyml`,
  SpecialWeapon: `Work/Gyml/Sp_${id}.spl__WeaponInfoSpecial.gyml`,
});

// One body per path, for each commit. Gear ids are suffixes; each slot gets the same set.
function files(v: Version): Record<string, Buffer> {
  const slot = (prefix: string) =>
    v.gear.map((g) => ({ __RowId: `${prefix}_${g}`, HowToGet: 'Shop' }));
  const names = {
    'CommonMsg/Weapon/WeaponName_Main': Object.fromEntries(v.kits.map((k) => [k, `Kit ${k}`])),
    'CommonMsg/Gear/GearName_Head': Object.fromEntries(v.gear.map((g) => [g, `Hat ${g}`])),
    'CommonMsg/Gear/GearName_Clothes': Object.fromEntries(v.gear.map((g) => [g, `Shirt ${g}`])),
    'CommonMsg/Gear/GearName_Shoes': Object.fromEntries(v.gear.map((g) => [g, `Shoes ${g}`])),
  };
  const json = (o: unknown) => Buffer.from(JSON.stringify(o));
  const out: Record<string, Buffer> = {
    'data/mush/1/WeaponInfoMain.json': json(v.kits.map(weapon)),
    'data/mush/1/GearInfoHead.json': json(slot('Hed')),
    'data/mush/1/GearInfoClothes.json': json(slot('Clt')),
    'data/mush/1/GearInfoShoes.json': json(slot('Shs')),
    'data/language/USen.json': json(names),
  };
  for (const k of v.kits) out[`images/weapon/Wst_${k}.png`] = Buffer.from(`not an image: ${k}`);
  for (const p of ['Hed', 'Clt', 'Shs'])
    for (const g of v.gear)
      out[`images/gear/${p}_${g}.png`] = Buffer.from(`not an image: ${p}_${g}`);
  return out;
}

export async function startDatamine(commits: Record<string, Version>) {
  const served = Object.fromEntries(Object.entries(commits).map(([c, v]) => [c, files(v)]));
  const server: Server = createServer((req, res) => {
    const [, commit, ...rest] = (req.url ?? '').split('/');
    const body = served[commit ?? '']?.[rest.join('/')];
    if (!body) {
      res.writeHead(404);
      return res.end();
    }
    res.end(body);
  });
  await new Promise<void>((r) => server.listen(0, r));
  const base = `http://localhost:${(server.address() as AddressInfo).port}/`;
  return {
    urlFor: (commit: string) => `${base}${commit}/`,
    close: () => new Promise<void>((r) => server.close(() => r())),
  };
}
